package com.hau.exam.presentation.support;import com.hau.exam.domain.model.*;import java.util.UUID;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.stereotype.Component;@Component public class ActorResolver{public Actor from(Jwt j){return new Actor(UUID.fromString(j.getSubject()),Role.valueOf(j.getClaimAsString("role")),j.getClaimAsString("facultyId"),j.getTokenValue());}}
